private readonly ConcurrentDictionary<string, User> _cache = new();

public User GetOrAddUser(string userId)
{
    return _cache.GetOrAdd(userId, id =>
    {
        // Factory runs only if key is missing
        return LoadUserFromDatabase(id);
    });
}

private readonly BlockingCollection<string> _queue = new();

public void StartProcessing(CancellationToken ct)
{
    Task.Run(() =>
    {
        foreach (var item in _queue.GetConsumingEnumerable(ct))
        {
            ProcessItem(item);
        }
    }, ct);
}

public void EnqueueWork(string workItem)
{
    _queue.Add(workItem);
}

public void Complete()
{
    _queue.CompleteAdding();
}
